using System;
using System.Linq;
using System.Reflection;
using KingmakerMountedCombat.Diagnostics;
using KingmakerMountedCombat.Integration;
using Newtonsoft.Json.Linq;
internal static class OwnedSchema1ContractTests
{
    private static int passed, failed;
    private static readonly string[] Ids = { "11111111-1111-4111-8111-111111111111", "22222222-2222-4222-8222-222222222222", "33333333-3333-4333-8333-333333333333", "44444444-4444-4444-8444-444444444444", "55555555-5555-4555-8555-555555555555" };
    private static SavedNativeActor Actor(string id) => new SavedNativeActor { Id=id, ReactionsRemaining=2, LastSurpriseTicks=17 };
    private static MountedArchiveData Fixture() => new MountedArchiveData { SchemaVersion=3, CampaignId="aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", AreaId=new string('b',32), GameTimeTicks=10000000, Policy=MountedSaveData.PairedPolicy, RulesId=MountedSaveData.Rules,
        Pairs=new[]{new SavedMountedPair { PairId=new string('c',32),Generation=7,ProfileId="medium-humanoid-horse-v1",Rider=Actor(Ids[0]),Mount=Actor(Ids[1]) }}, Participations=new SavedPairParticipation[0], Slots=new[]{new SavedMountedSlot{ActorId=Ids[0],Index=12,Kind=2},new SavedMountedSlot{ActorId=Ids[0],Index=13,Kind=3},new SavedMountedSlot{ActorId=Ids[2],Index=9,Kind=1},new SavedMountedSlot{ActorId=Ids[4],Index=10,Kind=4}} };
    private static JObject Field() => new JObject { ["phase"]="generated", ["gameTicks"]=10000000L,
        ["actors"]=new JArray(Ids.Select(id=>new JObject { ["native"]=JObject.FromObject(Actor(id),MountedSaveCodec.CreateSerializer()), ["prepared"]=false, ["inCombat"]=false, ["commandsEmpty"]=true, ["queuedCommands"]=0 })) };
    private static void Check(string name,Action body) { try { body();passed++;Console.WriteLine("PASS "+name); } catch(Exception e) { failed++;Console.WriteLine("FAIL "+name+": "+e); } }
    private static void Refuses(Action body) { var refused=false; try { body(); } catch(InvalidOperationException) { refused=true; } catch(System.IO.InvalidDataException) { refused=true; } if(!refused) throw new Exception("Expected refusal."); }
    private static void Archive(MountedArchiveData value,bool migrated=false) => Chunk7PersistenceScenario.ValidateOwnedSchema1Archive(value,"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",new string('b',32),Ids[0],Ids[1],migrated);
    public static int Main(string[] arguments)
    {
        if(arguments.Length!=1)throw new ArgumentException("Exact Unity dependency path required for the unchanged installed JSON assembly.");
        AppDomain.CurrentDomain.AssemblyResolve+=(sender,request)=>new AssemblyName(request.Name).Name=="UnityEngine"?Assembly.LoadFrom(arguments[0]):null;
        Check("one settled owner retains every representable unrelated slot",()=>{var a=Fixture();var before=MountedArchiveCodec.Encode(a);Archive(a);if(MountedArchiveCodec.Encode(a)!=before)throw new Exception("Observation mutated source.");});
        foreach(var kind in new[]{1,2,3,4})Check("unrelated historical slot kind "+kind,()=>{var a=Fixture();a.Slots[3].Kind=kind;Archive(a);});
        foreach(var fault in new[]{"pair2","participation","combat","debt","kind5","slots129","other-role","other-profile","generation2"})Check("actual archive refuses "+fault,()=>{var a=Fixture();switch(fault){case "pair2":a.Pairs=a.Pairs.Concat(new[]{new SavedMountedPair{PairId=new string('d',32),Generation=1,ProfileId="medium-humanoid-horse-v1",Rider=Actor(Ids[2]),Mount=Actor(Ids[3])}}).ToArray();break;case "participation":a.Participations=new[]{new SavedPairParticipation()};break;case "combat":a.Combat=new SavedCombatData();break;case "debt":a.Pairs[0].Rider.Swift=1;break;case "kind5":a.Slots[3].Kind=5;break;case "slots129":a.Slots=Enumerable.Range(0,129).Select(i=>new SavedMountedSlot{ActorId=Ids[2],Index=i,Kind=1}).ToArray();break;case "other-role":a.Pairs[0].Rider.Id=Ids[2];break;case "other-profile":a.Pairs[0].ProfileId="medium-humanoid-mammoth-v1";break;case "generation2":a.Pairs[0].Generation=2;break;}Refuses(()=>Archive(a,fault=="generation2"));});
        Check("actual full field accepts unchanged native values without writes",()=>{var a=Field();var before=a.ToString();var b=(JObject)a.DeepClone();b["gameTicks"]=10000100L;Chunk7PersistenceScenario.ValidateOwnedSchema1PreservedField(a,b,Ids);if(a.ToString()!=before)throw new Exception("Input changed.");});
        foreach(var fault in new[]{"missing","duplicate","prepared","reactions","surprise","debt","queued","combat","nonempty","clock","array-native","string-prepared"})Check("actual full-field refusal "+fault,()=>{var a=Field();var b=(JObject)a.DeepClone();var rows=(JArray)b["actors"];var row=rows[4];switch(fault){case "missing":rows.RemoveAt(4);break;case "duplicate":row["native"]["Id"]=Ids[0];break;case "prepared":row["prepared"]=true;break;case "reactions":row["native"]["ReactionsRemaining"]=3;break;case "surprise":row["native"]["LastSurpriseTicks"]=18;break;case "debt":row["native"]["Move"]=1;break;case "queued":row["queuedCommands"]=1;break;case "combat":row["inCombat"]=true;break;case "nonempty":row["commandsEmpty"]=false;break;case "clock":b["gameTicks"]=9999999L;break;case "array-native":row["native"]=new JArray(row["native"].DeepClone());break;case "string-prepared":row["prepared"]="False";break;}Refuses(()=>Chunk7PersistenceScenario.ValidateOwnedSchema1PreservedField(a,b,Ids));});
        Check("unchanged historical decoder retains unrelated controls and deliberate schema3 writer",()=>{var a=Fixture();var p=a.Pairs[0];var old=new JObject { ["SchemaVersion"]=1,["CampaignId"]=a.CampaignId,["AreaId"]=a.AreaId,["GameTimeTicks"]=a.GameTimeTicks,["Policy"]=a.Policy,["RulesId"]=a.RulesId,["Mounted"]=true,["ProfileId"]=p.ProfileId,["Rider"]=JObject.FromObject(p.Rider,MountedSaveCodec.CreateSerializer()),["Mount"]=JObject.FromObject(p.Mount,MountedSaveCodec.CreateSerializer()),["Slots"]=JArray.FromObject(a.Slots,MountedSaveCodec.CreateSerializer())};var read=MountedArchiveCodec.Decode(old.ToString());if(read.Kind!=MountedSaveReadKind.Current||read.SourceSchema!=1)throw new Exception(read.Feedback);Archive(read.Data,true);if(!JToken.DeepEquals(old["Slots"],JArray.FromObject(read.Data.Slots,MountedSaveCodec.CreateSerializer())))throw new Exception("Slots dropped.");var saved=MountedArchiveCodec.Decode(NativeMountedSaveFormat.CaptureOrPreserve(read,()=>read.Data));if(saved.SourceSchema!=3)throw new Exception("Default native writer changed.");});
        Check("historical encoding grants no Writer1 authority",()=>{Refuses(()=>NativeMountedSaveFormat.Encode(new MountedSaveData{SchemaVersion=1}));if(NativeMountedSaveFormat.WriterSchema!=2||NativeMountedSaveFormat.SelectedWriterSchema!=3)throw new Exception("Default writer policy changed.");});
        Check("native unrelated absent hotbar remains absent",()=>{var owner=new object();var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,null);if(!observation.Preserved(owner,null)||observation.Preserved(owner,new object[0])||observation.Preserved(new object(),null))throw new Exception("Absent collection custody changed.");});
        Check("native unrelated empty collection retains exact identity",()=>{var owner=new object();var slots=new object[0];var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots);if(!observation.Preserved(owner,slots)||observation.Preserved(owner,new object[0])||observation.Preserved(owner,null))throw new Exception("Empty collection identity changed.");});
        Check("native unrelated slots retain object order and null elements",()=>{var owner=new object();var first=new object();var second=new object();var slots=new object[]{first,null,second};var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots);if(!observation.Preserved(owner,slots))throw new Exception("Exact slots lost.");slots[0]=second;slots[2]=first;if(observation.Preserved(owner,slots))throw new Exception("Reordered objects accepted.");});
        Check("native unrelated equal-valued replacement is rejected",()=>{var owner=new object();var slots=new object[]{new string(new[]{'a'})};var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots);slots[0]=new string(new[]{'a'});if(observation.Preserved(owner,slots))throw new Exception("Value equality borrowed native object custody.");});
        Check("native unrelated collection count change is rejected",()=>{var owner=new object();var value=new object();var slots=new[]{value};var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots);if(observation.Preserved(owner,new[]{value,new object()}))throw new Exception("Count-changing replacement array accepted.");});
        Check("native unrelated collection bound follows installed native capacity",()=>{Refuses(()=>Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(new object(),new object[141]));foreach(var count in new[]{128,129,140}){var owner=new object();var slots=new object[count];var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots);if(!observation.Preserved(owner,slots))throw new Exception("Finite exact native array lost at "+count);}});
        Check("inactive owned template cleanup preserves every unrelated slot object",()=>{var owner=new object();var native=new object();var template=new object();var slots=new object[]{native,template,null};var observed=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots,item=>ReferenceEquals(item,template));if(observed.Preserved(owner,slots,item=>item==null))throw new Exception("Stale owned template was not required to clear.");slots[1]=null;if(!observed.Preserved(owner,slots,item=>item==null))throw new Exception("Lawful owned template cleanup was rejected.");slots[0]=new object();if(observed.Preserved(owner,slots,item=>item==null))throw new Exception("Unrelated replacement was masked.");});
        Check("inactive template classification cannot admit another ability replacement",()=>{var owner=new object();var template=new object();var slots=new object[]{template};var observed=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots,item=>ReferenceEquals(item,template));slots[0]=new object();if(observed.Preserved(owner,slots,item=>item==null))throw new Exception("Foreign ability accepted as cleanup.");});
        Check("a cleared owned template needs its explicit serialization classifier",()=>{var owner=new object();var template=new object();var slots=new object[]{template};var observed=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots,item=>ReferenceEquals(item,template));slots[0]=null;if(observed.Preserved(owner,slots))throw new Exception("Unscoped cleanup accepted.");});
        Check("native hotbar seam accepts only finite reference arrays",()=>{var type=typeof(Chunk7PersistenceScenario.OwnedSchema1HotbarObservation);var flags=BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance;foreach(var name in new[]{"Capture","Preserved"})if(type.GetMethod(name,flags).GetParameters()[1].ParameterType!=typeof(object[]))throw new Exception("Native finite array seam broadened to arbitrary enumerable.");});
        Check("all140 native entries remain read-only with exact array and owner custody",()=>{var owner=new object();var slots=Enumerable.Range(0,140).Select(i=>i%7==0?null:new object()).ToArray();var before=(object[])slots.Clone();var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots);if(!observation.Preserved(owner,slots)||observation.Preserved(new object(),slots)||observation.Preserved(owner,(object[])slots.Clone())||observation.Preserved(owner,null))throw new Exception("Full native array identity custody changed.");for(var i=0;i<slots.Length;i++)if(!ReferenceEquals(slots[i],before[i]))throw new Exception("Observer mutated slot "+i);});
        foreach(var index in Enumerable.Range(0,140))Check("native140 refuses replacement at index "+index,()=>{var owner=new object();var slots=Enumerable.Range(0,140).Select(i=>i%7==0?null:new object()).ToArray();var original=slots[index];var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots);slots[index]=new object();if(observation.Preserved(owner,slots))throw new Exception("Replaced element was not observed.");slots[index]=original;if(!observation.Preserved(owner,slots))throw new Exception("Restored exact observation lost.");});
        Check("native140 tail order128and139 is preserved",()=>{var owner=new object();var slots=new object[140];slots[128]=new object();slots[139]=new object();var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots);var temporary=slots[128];slots[128]=slots[139];slots[139]=temporary;if(observation.Preserved(owner,slots))throw new Exception("Tail reorder accepted.");});
        Check("native140 equal-valued tail replacement is refused",()=>{var owner=new object();var slots=new object[140];slots[139]=new string(new[]{'z'});var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots);slots[139]=new string(new[]{'z'});if(observation.Preserved(owner,slots))throw new Exception("Equal-valued tail replacement borrowed custody.");});
        Check("native140 null tail cannot disappear into another collection",()=>{var owner=new object();var slots=new object[140];var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots);if(!observation.Preserved(owner,slots)||observation.Preserved(owner,new object[128])||observation.Preserved(owner,new object[141]))throw new Exception("Array length or identity was ignored.");});
        Check("native140 permits only captured inactive tail template cleanup",()=>{var owner=new object();var native=new object();var template=new object();var slots=new object[140];slots[128]=native;slots[139]=template;var calls=0;var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots,item=>{calls++;return ReferenceEquals(item,template);});if(calls!=140||!ReferenceEquals(slots[128],native)||!ReferenceEquals(slots[139],template))throw new Exception("Capture skipped tail or mutated source.");if(observation.Preserved(owner,slots,item=>item==null))throw new Exception("Stale tail template need not clear.");slots[139]=null;if(!observation.Preserved(owner,slots,item=>item==null)||observation.Preserved(owner,slots))throw new Exception("Explicit tail cleanup classification lost.");slots[128]=new object();if(observation.Preserved(owner,slots,item=>item==null))throw new Exception("Tail template masked unrelated change.");});
        Check("native140 rejects foreign replacement at captured inactive tail",()=>{var owner=new object();var template=new object();var slots=new object[140];slots[139]=template;var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots,item=>ReferenceEquals(item,template));slots[139]=new object();if(observation.Preserved(owner,slots,item=>item==null))throw new Exception("Foreign tail ability accepted as empty.");});
        Check("native140 does not classify an unrelated null tail as an inactive template",()=>{var owner=new object();var slots=new object[140];var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots,item=>false);slots[139]=new object();if(observation.Preserved(owner,slots,item=>true))throw new Exception("Cleanup callback replaced capture-time classification.");});
        Check("native140 covariant array retains typed collection identity",()=>{var owner=new object();var slots=new string[140];slots[128]="native";slots[139]=new string(new[]{'t'});var observation=Chunk7PersistenceScenario.OwnedSchema1HotbarObservation.Capture(owner,slots);if(!observation.Preserved(owner,slots))throw new Exception("Covariant native reference array lost.");slots[139]=new string(new[]{'t'});if(observation.Preserved(owner,slots))throw new Exception("Covariant element replacement accepted.");});
        Console.WriteLine("TOTAL PASS="+passed+" FAIL="+failed);return failed==0?0:1;
    }
}
